-- Commerce OS schema. Foreign keys are deferred so one command can write related rows in any order.
CREATE TABLE workspace (id int PRIMARY KEY CHECK (id = 1), schema int NOT NULL, version bigint NOT NULL DEFAULT 0, seq jsonb NOT NULL DEFAULT '{}', settings jsonb NOT NULL DEFAULT '{}', roadmap jsonb NOT NULL DEFAULT '{}');

CREATE TABLE users (id bigserial PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK (role IN ('owner','operations','warehouse','finance','driver')), driver_id text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK (role <> 'driver' OR driver_id IS NOT NULL));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON sessions (user_id);

CREATE TABLE skus ("_seq" bigserial, id text PRIMARY KEY, name text NOT NULL, variant text, price numeric(14,2) NOT NULL CHECK (price >= 0), min numeric(14,2) NOT NULL DEFAULT 0);
CREATE TABLE materials ("_seq" bigserial, id text PRIMARY KEY, name text NOT NULL, unit text NOT NULL, cost numeric(14,2) NOT NULL, category text NOT NULL, min numeric(14,2) NOT NULL DEFAULT 0);
CREATE TABLE boms ("_seq" bigserial, id text PRIMARY KEY REFERENCES skus(id) DEFERRABLE INITIALLY DEFERRED, lines jsonb NOT NULL, labor numeric(14,2) NOT NULL, overhead numeric(14,2) NOT NULL);
CREATE TABLE customers ("_seq" bigserial, id text PRIMARY KEY, name text NOT NULL, phone text NOT NULL UNIQUE, area text, address text, alt_addresses jsonb, delivery_notes text, preferred_time text, tags jsonb, notes jsonb, at timestamptz);
CREATE TABLE contacts ("_seq" bigserial, id text PRIMARY KEY, customer_id text NOT NULL REFERENCES customers(id) DEFERRABLE INITIALLY DEFERRED, channel text, direction text, summary text NOT NULL, follow_up text, at timestamptz NOT NULL, "by" text);
CREATE TABLE couriers ("_seq" bigserial, id text PRIMARY KEY, name text NOT NULL, ship_rate numeric(14,2) NOT NULL, return_rate numeric(14,2) NOT NULL, cod_fee numeric(14,2) NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE drivers ("_seq" bigserial, id text PRIMARY KEY, name text NOT NULL, phone text NOT NULL, vehicle text, zones text, availability text NOT NULL, active boolean NOT NULL DEFAULT true, at timestamptz);
CREATE TABLE campaigns ("_seq" bigserial, id text PRIMARY KEY, name text NOT NULL, platform text, start date, "end" date, budget numeric(14,2) NOT NULL DEFAULT 0, reported_roas numeric(10,2) NOT NULL DEFAULT 0, source text);
CREATE TABLE spend ("_seq" bigserial, id text PRIMARY KEY, campaign_id text NOT NULL REFERENCES campaigns(id) DEFERRABLE INITIALLY DEFERRED, amount numeric(14,2) NOT NULL, at timestamptz NOT NULL, note text, "by" text);

CREATE TABLE orders ("_seq" bigserial, id bigint PRIMARY KEY, at timestamptz NOT NULL, customer_id text NOT NULL REFERENCES customers(id) DEFERRABLE INITIALLY DEFERRED, address text, area text, instructions text, channel text, source text NOT NULL, campaign_id text REFERENCES campaigns(id) DEFERRABLE INITIALLY DEFERRED, status text NOT NULL CHECK (status IN ('New','Confirmed','Processing','Ready','Shipped','Failed Delivery','Partially Delivered','Delivered','Partially Returned','Returned','Cancelled')), payment_method text, discount numeric(14,2) NOT NULL DEFAULT 0, delivery_fee numeric(14,2) NOT NULL DEFAULT 0, notes jsonb, external_ref text, related_order_id bigint REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, confirmed_at timestamptz, cancelled_at timestamptz, shipped_at timestamptz, delivered_at timestamptz, returned_at timestamptz);
CREATE UNIQUE INDEX orders_external_ref_unique ON orders (external_ref) WHERE external_ref IS NOT NULL;
CREATE INDEX ON orders (customer_id); CREATE INDEX ON orders (campaign_id); CREATE INDEX ON orders (status); CREATE INDEX ON orders (at);

CREATE TABLE lines ("_seq" bigserial, id text PRIMARY KEY, order_id bigint NOT NULL REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, sku text NOT NULL REFERENCES skus(id) DEFERRABLE INITIALLY DEFERRED, name text, variant text, qty int NOT NULL CHECK (qty > 0), price numeric(14,2) NOT NULL, discount numeric(14,2) NOT NULL DEFAULT 0, unit_cost numeric(14,2) NOT NULL, reserved int NOT NULL DEFAULT 0 CHECK (reserved >= 0), dispatched int NOT NULL DEFAULT 0, delivered int NOT NULL DEFAULT 0, returned int NOT NULL DEFAULT 0, pending_return int NOT NULL DEFAULT 0 CHECK (pending_return >= 0), undelivered_back int NOT NULL DEFAULT 0, CHECK (returned <= delivered), CHECK (delivered + undelivered_back <= dispatched));
CREATE INDEX ON lines (order_id); CREATE INDEX ON lines (sku);

CREATE TABLE deliveries ("_seq" bigserial, id text PRIMARY KEY, order_id bigint NOT NULL REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, mode text NOT NULL CHECK (mode IN ('driver','courier')), carrier_id text NOT NULL, carrier_key text NOT NULL, status text NOT NULL, custody text NOT NULL, area text, assigned_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, picked_up_at timestamptz, completed_at timestamptz, returned_at timestamptz, retry_at timestamptz, return_started_at timestamptz, items jsonb NOT NULL, attempts jsonb NOT NULL, history jsonb NOT NULL, tracking text, cost numeric(14,2) NOT NULL DEFAULT 0, return_cost numeric(14,2) NOT NULL DEFAULT 0, cod_fee numeric(14,2) NOT NULL DEFAULT 0, predecessor_id text, successor_id text);
-- The database itself refuses a second active assignment for one order.
CREATE UNIQUE INDEX deliveries_one_active_per_order ON deliveries (order_id) WHERE status NOT IN ('Delivered','Returned to Warehouse','Cancelled Assignment','Handed Over');
CREATE INDEX ON deliveries (carrier_key); CREATE INDEX ON deliveries (status);

CREATE TABLE payments ("_seq" bigserial, id text PRIMARY KEY, order_id bigint NOT NULL REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, delivery_id text REFERENCES deliveries(id) DEFERRABLE INITIALLY DEFERRED, kind text NOT NULL CHECK (kind IN ('collection','refund')), method text NOT NULL, amount numeric(14,2) NOT NULL, holder_key text NOT NULL, driver_id text, ref text NOT NULL UNIQUE, at timestamptz NOT NULL, "by" text, fee numeric(14,2) NOT NULL DEFAULT 0, note text, reason text);
CREATE INDEX ON payments (order_id); CREATE INDEX ON payments (holder_key); CREATE INDEX ON payments (at);

CREATE TABLE handovers ("_seq" bigserial, id text PRIMARY KEY, driver_id text NOT NULL REFERENCES drivers(id) DEFERRABLE INITIALLY DEFERRED, ref text NOT NULL UNIQUE, at timestamptz NOT NULL, received_by text NOT NULL, amount numeric(14,2) NOT NULL CHECK (amount > 0), declared numeric(14,2), note text, "by" text);
CREATE TABLE handover_allocs ("_seq" bigserial, id text PRIMARY KEY, handover_id text NOT NULL REFERENCES handovers(id) DEFERRABLE INITIALLY DEFERRED, delivery_id text NOT NULL REFERENCES deliveries(id) DEFERRABLE INITIALLY DEFERRED, order_id bigint NOT NULL REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, driver_id text NOT NULL, amount numeric(14,2) NOT NULL CHECK (amount > 0), UNIQUE (handover_id, delivery_id));
CREATE INDEX ON handover_allocs (delivery_id); CREATE INDEX ON handover_allocs (order_id);
CREATE TABLE settlements ("_seq" bigserial, id text PRIMARY KEY, courier_id text NOT NULL REFERENCES couriers(id) DEFERRABLE INITIALLY DEFERRED, ref text NOT NULL UNIQUE, at timestamptz NOT NULL, net numeric(14,2) NOT NULL, note text, "by" text);
CREATE TABLE settlement_allocs ("_seq" bigserial, id text PRIMARY KEY, settlement_id text NOT NULL REFERENCES settlements(id) DEFERRABLE INITIALLY DEFERRED, delivery_id text NOT NULL REFERENCES deliveries(id) DEFERRABLE INITIALLY DEFERRED, order_id bigint NOT NULL REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, net numeric(14,2) NOT NULL, UNIQUE (settlement_id, delivery_id));
CREATE INDEX ON settlement_allocs (delivery_id); CREATE INDEX ON settlement_allocs (order_id);
CREATE TABLE driver_expenses ("_seq" bigserial, id text PRIMARY KEY, driver_id text NOT NULL REFERENCES drivers(id) DEFERRABLE INITIALLY DEFERRED, delivery_id text REFERENCES deliveries(id) DEFERRABLE INITIALLY DEFERRED, category text NOT NULL, amount numeric(14,2) NOT NULL CHECK (amount > 0), paid_from_cash boolean NOT NULL, status text NOT NULL CHECK (status IN ('Pending','Approved','Rejected')), at timestamptz NOT NULL, note text, "by" text, decided_at timestamptz, decided_by text);
CREATE TABLE discrepancies ("_seq" bigserial, id text PRIMARY KEY, order_id bigint REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, delivery_id text, carrier_key text, type text NOT NULL, amount numeric(14,2) NOT NULL, reason text, status text NOT NULL CHECK (status IN ('Open','Resolved')), at timestamptz NOT NULL, resolution text, resolved_at timestamptz);
CREATE TABLE cases ("_seq" bigserial, id text PRIMARY KEY, order_id bigint NOT NULL REFERENCES orders(id) DEFERRABLE INITIALLY DEFERRED, type text NOT NULL CHECK (type IN ('Return','Exchange')), items jsonb NOT NULL, reason text, status text NOT NULL, at timestamptz NOT NULL, accepted_at timestamptz, return_cost numeric(14,2) NOT NULL DEFAULT 0, replacement_order_id bigint, resolution text);
CREATE INDEX ON cases (order_id);
CREATE TABLE production ("_seq" bigserial, id text PRIMARY KEY, sku text NOT NULL REFERENCES skus(id) DEFERRABLE INITIALLY DEFERRED, qty int NOT NULL CHECK (qty > 0), due text, status text NOT NULL CHECK (status IN ('Planned','WIP','Completed','Cancelled')), at timestamptz NOT NULL, started_at timestamptz, completed_at timestamptz, unit_cost numeric(14,2) NOT NULL);
CREATE TABLE expenses ("_seq" bigserial, id text PRIMARY KEY, name text NOT NULL, category text, amount numeric(14,2) NOT NULL CHECK (amount > 0), at timestamptz NOT NULL, "by" text);

-- Stock journal and activity log are append-only at the database level.
CREATE TABLE movements ("_seq" bigserial, id bigint PRIMARY KEY, at timestamptz NOT NULL, item text NOT NULL, item_type text NOT NULL CHECK (item_type IN ('sku','material')), qty numeric(14,2) NOT NULL, kind text NOT NULL, key text, ref text, note text, "by" text);
CREATE UNIQUE INDEX movements_key_unique ON movements (key) WHERE key IS NOT NULL;
CREATE INDEX ON movements (item);
CREATE TABLE events ("_seq" bigserial, id bigint PRIMARY KEY, at timestamptz NOT NULL, "by" text, text text NOT NULL, order_id bigint, driver_id text, customer_id text, delivery_id text);
CREATE INDEX ON events (order_id); CREATE INDEX ON events (driver_id); CREATE INDEX ON events (at);
CREATE FUNCTION forbid_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME; END $$;
CREATE TRIGGER movements_append_only BEFORE UPDATE OR DELETE ON movements FOR EACH ROW EXECUTE FUNCTION forbid_change();
CREATE TRIGGER events_append_only BEFORE UPDATE OR DELETE ON events FOR EACH ROW EXECUTE FUNCTION forbid_change();
